#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>

typedef struct {
    char* s;
    int pos;
    int len;
} Tok;

static void skipWS(Tok* t) {
    while (t->pos < t->len &&
           (t->s[t->pos] == ' ' || t->s[t->pos] == ',' ||
            t->s[t->pos] == '\t' || t->s[t->pos] == '\n' ||
            t->s[t->pos] == '\r')) {
        t->pos++;
    }
}

static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;
    int start = t->pos;

    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
    } else {
        while (t->pos < t->len &&
               t->s[t->pos] != ',' && t->s[t->pos] != ']') {
            t->pos++;
        }
    }

    int tokenLen = t->pos - start;
    char* token = (char*)malloc((size_t)tokenLen + 1);
    if (!token) return NULL;
    memcpy(token, t->s + start, (size_t)tokenLen);
    token[tokenLen] = '\0';
    while (tokenLen > 0 && (token[tokenLen - 1] == ' ' || token[tokenLen - 1] == '\t')) {
        token[--tokenLen] = '\0';
    }
    return token;
}

static int parseInt(Tok* t) {
    char* tok = nextToken(t);
    int value = tok ? atoi(tok) : 0;
    free(tok);
    return value;
}

static int* parseIntArray(Tok* t, int* outSize) {
    char* tok = nextToken(t);
    if (!tok || strcmp(tok, "[]") == 0) {
        free(tok);
        *outSize = 0;
        return NULL;
    }

    int len = (int)strlen(tok);
    char* inner = (char*)malloc((size_t)len - 1);
    memcpy(inner, tok + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(tok);

    int size = 1;
    for (int i = 0; inner[i]; ++i) {
        if (inner[i] == ',') ++size;
    }

    int* a = (int*)malloc((size_t)size * sizeof(int));
    Tok t2 = {inner, 0, (int)strlen(inner)};
    for (int i = 0; i < size; ++i) a[i] = parseInt(&t2);

    free(inner);
    *outSize = size;
    return a;
}

